def condensation(amine,tag,final,enamine=False):
 y='OH' if amine=='NH2OH' else 'NH2'
 charged='NH+Me2' if enamine else 'NH2+–'+y
 neutral='NMe2' if enamine else 'NH–'+y
 iminium='N+Me2' if enamine else 'N+(H)–'+y
 steps=[E('pt','Me2C={o|O:} + {h|H}–{w|OH2+}','Me2C=OH+ + H2O','Carbonyl oxygen accepts a proton.', [('o','h'),(('h','w'),'w')]),
 E('add','Me2{c|C}={o|OH+} + {n|:'+amine+'}','Me2C(OH)('+charged+')','Nitrogen attacks carbonyl carbon; the C=O pi pair returns to O, giving the carbinolammonium form.', [('n','c'),(('c','o'),'o')]),
 E('pt','Me2C(OH)–{n|N+}('+('Me)(Me' if enamine else 'H)('+y)+')–{h|H} + {w|:OH2}','Me2C(OH)('+neutral+') + H3O+','Water removes one N-bound proton.', [('w','h'),(('n','h'),'n')]),
 E('pt','Me2C({o|O:H})('+neutral+') + {h|H}–{w|OH2+}','Me2C(OH2+)('+neutral+') + H2O','Protonation makes the hydroxyl group a water leaving group.', [('o','h'),(('h','w'),'w')]),
 E('collapse','Me2{c|C}({o|OH2+})–{n|N:}('+('Me)Me' if enamine else 'H)–'+y),'Me2C='+iminium+' + H2O','Nitrogen lone-pair donation forms C=N as water leaves.', [('n',('c','n')),(('c','o'),'o')])]
 if enamine:steps.append(E('polar','{a|CH2}({h|H})–{c|C}(={n|N+Me2})–CH3 + {b|:OH2}',final+' + H3O+','Water removes alpha H; the C–H pair forms C=C and C=N pi electrons return to N.', [('b','h'),(('a','h'),('a','c')),(('c','n'),'n')],title='Alpha deprotonation'))
 else:steps.append(E('pt','Me2C={n|N+}('+y+')–{h|H} + {b|:OH2}',final+' + H3O+','Water removes the remaining iminium N–H proton.', [('b','h'),(('n','h'),'n')]))
 return steps
